import django
from django import forms

class CustomErrorList(forms.utils.ErrorList):
    def __str__(self):
        return self.as_ul()

class MyForm(forms.Form):
    name = forms.CharField()

class MyFormSet(forms.BaseFormSet):
    def clean(self):
        raise forms.ValidationError('Formset-wide error')

FormSet = forms.formset_factory(MyForm, formset=MyFormSet, error_class=CustomErrorList)
fs = FormSet(data={'form-TOTAL_FORMS': '1', 'form-INITIAL_FORMS': '0'})
print(repr(fs.non_form_errors()))
print(fs.non_form_errors())
